python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from pathlib import Path
import os
os.makedirs('/root/output', exist_ok=True)
path=Path('/root/data/workbook.xlsx')
wb=load_workbook(path, data_only=False)
print('Workbook:', path)
print('Sheets:', wb.sheetnames)
for ws in wb.worksheets:
    print(f"Sheet {ws.title}: max_row={ws.max_row}, max_column={ws.max_column} ({get_column_letter(ws.max_column)})")

ws=wb['Task']
print('\n=== Task sheet inspection ===')
print('Column D rows 12-17, 19-24, 26-31 (series codes and nearby labels):')
for start,end in [(12,17),(19,24),(26,31)]:
    print(f'Block rows {start}-{end}:')
    for r in range(start,end+1):
        nearby={get_column_letter(c): ws.cell(r,c).value for c in range(1,8) if ws.cell(r,c).value is not None}
        print(f'  row {r}: D={ws.cell(r,4).value!r}; nearby A:G={nearby}')
print('\nRow 10 columns H-L (years):')
print({get_column_letter(c): ws.cell(10,c).value for c in range(8,13)})
print('\nRows 35-40 column D for service names and nearby labels A:G:')
for r in range(35,41):
    nearby={get_column_letter(c): ws.cell(r,c).value for c in range(1,8) if ws.cell(r,c).value is not None}
    print(f'  row {r}: D={ws.cell(r,4).value!r}; nearby A:G={nearby}')
print('\nH42:L47 labels and nearby columns A:G:')
for r in range(42,48):
    row_hl={get_column_letter(c): ws.cell(r,c).value for c in range(8,13)}
    nearby={get_column_letter(c): ws.cell(r,c).value for c in range(1,8) if ws.cell(r,c).value is not None}
    print(f'  row {r}: A:G={nearby}; H:L={row_hl}')
print('\nH50:L50 area and labels near row 50 (rows 48-52, cols A-L non-empty):')
for r in range(48,53):
    vals={get_column_letter(c): ws.cell(r,c).value for c in range(1,13) if ws.cell(r,c).value is not None}
    print(f'  row {r}: {vals}')

wsd=wb['Data']
print('\n=== Data sheet rows 21-38 inspection ===')
# print cells A:Z in rows 21-38, trimming all-empty trailing columns but show coordinates/values
for r in range(21,39):
    vals=[]
    for c in range(1, min(wsd.max_column, 30)+1):
        v=wsd.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}={v!r}')
    print(f'  row {r}: ' + ('; '.join(vals) if vals else '(all empty in A:AD)'))
print('\nData rows 21-38 columns with any non-empty values:')
cols=[]
for c in range(1, wsd.max_column+1):
    if any(wsd.cell(r,c).value is not None for r in range(21,39)):
        cols.append(c)
print([(get_column_letter(c), c) for c in cols])
PY

